import{_ as e,o as t,c as r,a6 as o}from"./chunks/framework.DNkVJs23.js";const f=JSON.parse('{"title":"常見問題","description":"","frontmatter":{"head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hant/faq/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/zh-hant/faq/"}],["meta",{"property":"og:title","content":"常見問題 | 蒼藍星圖鑑"}],["meta",{"property":"og:description","content":"蒼藍星圖鑑：查詢魔物弱點、裝備性能與素材來源，依目標技能搜尋配裝。支援《荒野》《崛起＋破曉》《世界＋冰原》。"}]]},"headers":[],"relativePath":"zh-hant/faq/index.md","filePath":"zh-hant/faq/index.md"}'),n={name:"zh-hant/faq/index.md"};function h(i,a,l,d,p,s){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="常見問題" tabindex="-1">常見問題 <a class="header-anchor" href="#常見問題" aria-label="Permalink to &quot;常見問題&quot;">​</a></h1><h2 id="支援哪些遊戲" tabindex="-1">支援哪些遊戲？ <a class="header-anchor" href="#支援哪些遊戲" aria-label="Permalink to &quot;支援哪些遊戲？&quot;">​</a></h2><p>支援《魔物獵人：荒野》《崛起＋破曉》與《世界＋冰原》。各遊戲使用獨立資料，可在應用程式首頁切換並查看對應內容。</p><h2 id="現在可以下載嗎" tabindex="-1">現在可以下載嗎？ <a class="header-anchor" href="#現在可以下載嗎" aria-label="Permalink to &quot;現在可以下載嗎？&quot;">​</a></h2><p>HarmonyOS 版本已於<a href="https://appgallery.huawei.com/app/detail?id=com.eurekaffeine.monsterhunterdex&amp;channelId=SHARE&amp;source=appshare" target="_blank" rel="noreferrer">華為應用程式市場</a>上架。Android 版本已於 <a href="https://play.google.com/store/apps/details?id=com.eurekaffeine.mhd" target="_blank" rel="noreferrer">Google Play</a> 上架，iOS 版本正在準備發布。<a href="./../#download">下載應用程式</a>區域提供目前的上架狀態與下載連結，實際供應情形可能依地區與裝置而異。</p><h2 id="是否支援離線使用" tabindex="-1">是否支援離線使用？ <a class="header-anchor" href="#是否支援離線使用" aria-label="Permalink to &quot;是否支援離線使用？&quot;">​</a></h2><p>支援。圖鑑資料隨應用程式內建，瀏覽、搜尋、收藏與配裝搜尋皆在本機執行。瀏覽外部網站或下載應用程式更新時需要網路連線。</p><h2 id="配裝搜尋支援哪些條件" tabindex="-1">配裝搜尋支援哪些條件？ <a class="header-anchor" href="#配裝搜尋支援哪些條件" aria-label="Permalink to &quot;配裝搜尋支援哪些條件？&quot;">​</a></h2><p>可設定目標技能與等級，固定或排除指定裝備，並依已持有的裝飾品數量篩選防具組合。《崛起》另支援自有護石與傀異鍊化防具。</p><p>搜尋結果取決於目前的遊戲資料與設定條件。配裝搜尋目前不包含傷害計算功能。</p><h2 id="支援哪些語言" tabindex="-1">支援哪些語言？ <a class="header-anchor" href="#支援哪些語言" aria-label="Permalink to &quot;支援哪些語言？&quot;">​</a></h2><p>應用程式支援 14 種語言：繁體中文、簡體中文、英語、日語、韓語、法語、德語、西班牙語（西班牙）、西班牙語（拉丁美洲）、義大利語、俄語、葡萄牙語（巴西）、波蘭語及阿拉伯語。缺少翻譯的遊戲內容可能顯示英文；拉丁美洲西班牙語會先採用西班牙地區的譯文。網站截圖與所選語言一致。</p><h2 id="這是-capcom-官方應用程式嗎" tabindex="-1">這是 CAPCOM 官方應用程式嗎？ <a class="header-anchor" href="#這是-capcom-官方應用程式嗎" aria-label="Permalink to &quot;這是 CAPCOM 官方應用程式嗎？&quot;">​</a></h2><p>不是。蒼藍星圖鑑是由愛好者獨立開發的非商業應用程式，與 CAPCOM 無關聯，亦未獲其認可或支援。Monster Hunter 的遊戲美術與資料歸 CAPCOM Co., Ltd. 所有。</p><h2 id="如何參與資料完善" tabindex="-1">如何參與資料完善？ <a class="header-anchor" href="#如何參與資料完善" aria-label="Permalink to &quot;如何參與資料完善？&quot;">​</a></h2><p>歡迎協助核對遊戲資料與翻譯，詳情請參閱<a href="./../others/">關於與支援</a>。回報資料問題時，請註明遊戲、魔物或裝備名稱、具體問題及可查證的來源。</p>',16)])])}const u=e(n,[["render",h]]);export{f as __pageData,u as default};
